const input = $json.body ?? $json;
for (const field of ['campaignId','approvedProviderId','approvedPackageId']) if (typeof input[field] !== 'string' || input[field].trim() === '') throw new Error(field + ' is required');
if (input.ownerApproval !== true) throw new Error('Explicit ownerApproval=true is required');
if (!Number.isSafeInteger(input.approvedAmountPaise) || input.approvedAmountPaise < 0) throw new Error('approvedAmountPaise must be integer paise');
return [{ json: { ...input, requestId: typeof input.requestId === 'string' ? input.requestId : 'transaction:' + input.campaignId } }];

const input = $('Validate Approved Transaction Input').item.json;
const campaign = $('Store Payment Campaign Lookup').item.json.data;
const options = $('Store Approved Option Lookup').item.json.data ?? [];
const option = options.find((item) => item.packageId === input.approvedPackageId);
const approvedPackage = $('Load Approved Package').first().json;
if (!campaign || campaign.status !== 'AWAITING_OWNER_APPROVAL') return [{ json: { eligible: false, failureCode: 'WRONG_CAMPAIGN_STATUS', campaign, option, approvedPackage, quote: $json } }];
if (!option || option.packageId !== input.approvedPackageId || !approvedPackage || approvedPackage.id !== input.approvedPackageId) return [{ json: { eligible: false, failureCode: 'PACKAGE_CHANGED', campaign, option, approvedPackage, quote: $json } }];
if ($json.available !== true) return [{ json: { eligible: false, failureCode: 'PROVIDER_UNAVAILABLE', campaign, option, approvedPackage, quote: $json } }];
if ($json.packageId !== approvedPackage.id || approvedPackage.providerId !== input.approvedProviderId || $json.merchantId !== approvedPackage.merchantId) return [{ json: { eligible: false, failureCode: 'MERCHANT_OR_PACKAGE_CHANGED', campaign, option, approvedPackage, quote: $json } }];
if (Number($json.livePricePaise) !== Number(input.approvedAmountPaise) || Number(option.totalCostPaise) !== Number(input.approvedAmountPaise) || Number(approvedPackage.pricePaise) !== Number(input.approvedAmountPaise)) return [{ json: { eligible: false, failureCode: 'PRICE_CHANGED', campaign, option, approvedPackage, quote: $json } }];
if (Number($json.livePricePaise) > Number(campaign.maxBudgetPaise)) return [{ json: { eligible: false, failureCode: 'BUDGET_EXCEEDED', campaign, option, approvedPackage, quote: $json } }];
if (Number(option.expectedCpaPaise) > Number(campaign.maxExpectedCpaPaise)) return [{ json: { eligible: false, failureCode: 'HIGH_CPA', campaign, option, approvedPackage, quote: $json } }];
if (Date.parse($json.publicationDeadlineAt) > Date.parse(campaign.slotStartAt) || Date.now() > Date.parse($json.publicationDeadlineAt)) return [{ json: { eligible: false, failureCode: 'DEADLINE_CHANGED', campaign, option, approvedPackage, quote: $json } }];
return [{ json: { eligible: true, failureCode: null, campaign, option, approvedPackage, quote: $json, input } }];

const configured = Number($env.N8N_MAX_PRAVA_POLLS || 5);
const count = Number.isSafeInteger(configured) && configured > 0 ? Math.min(configured, 10) : 5;
return Array.from({ length: count }, (_, index) => ({ json: { attempt: index + 1 } }));
